package com.company.platform.inventory.domain;
import java.time.Instant; import java.util.UUID;
public final class Reservation {private final UUID id,tenantId,orderId;private final String reference;private final Instant expiresAt,createdAt;private Instant updatedAt;private ReservationStatus status;private Reservation(UUID id,UUID t,UUID o,String r,ReservationStatus s,Instant e,Instant c,Instant u){if(t==null||o==null||r==null||r.isBlank()||e==null)throw new IllegalArgumentException("invalid reservation");this.id=id==null?UUID.randomUUID():id;tenantId=t;orderId=o;reference=r;status=s==null?ReservationStatus.PENDING:s;expiresAt=e;createdAt=c==null?Instant.now():c;updatedAt=u==null?createdAt:u;}public static Reservation create(UUID t,UUID o,String r,Instant e){return new Reservation(null,t,o,r,null,e,null,null);}public static Reservation rehydrate(UUID id,UUID t,UUID o,String r,ReservationStatus s,Instant e,Instant c,Instant u){return new Reservation(id,t,o,r,s,e,c,u);}public void reserve(){transition(ReservationStatus.RESERVED,ReservationStatus.PENDING,ReservationStatus.REQUESTED);}public void allocate(){transition(ReservationStatus.ALLOCATED,ReservationStatus.RESERVED);}public void fail(){transition(ReservationStatus.FAILED,ReservationStatus.PENDING,ReservationStatus.REQUESTED);}public void release(){transition(ReservationStatus.RELEASED,ReservationStatus.RESERVED,ReservationStatus.ALLOCATED);}public void consume(){transition(ReservationStatus.CONSUMED,ReservationStatus.RESERVED,ReservationStatus.ALLOCATED);}public void expire(){if(Instant.now().isBefore(expiresAt))throw new IllegalStateException("reservation has not expired");transition(ReservationStatus.EXPIRED,ReservationStatus.PENDING,ReservationStatus.RESERVED);}private void transition(ReservationStatus to,ReservationStatus... from){for(ReservationStatus s:from)if(status==s){status=to;updatedAt=Instant.now();return;}throw new IllegalStateException("invalid reservation transition");}public UUID id(){return id;}public UUID tenantId(){return tenantId;}public UUID orderId(){return orderId;}public String reference(){return reference;}public ReservationStatus status(){return status;}public Instant expiresAt(){return expiresAt;}public Instant createdAt(){return createdAt;}public Instant updatedAt(){return updatedAt;}}
